async fn report_check_interval (& mut self , install_source : InstallSource) { let now = self . time_source . now () ; match self . context . schedule . last_update_check_time { Some (PartialComplexTime :: Wall (t)) => match now . wall_duration_since (t) { Ok (interval) => self . report_metrics (Metrics :: UpdateCheckInterval { interval , clock : ClockType :: Wall , install_source , }) , Err (e) => warn ! ("Last check time is in the future: {}" , e) , } , Some (PartialComplexTime :: Complex (t)) => match now . mono . checked_duration_since (t . mono) { Some (interval) => self . report_metrics (Metrics :: UpdateCheckInterval { interval , clock : ClockType :: Monotonic , install_source , }) , None => error ! ("Monotonic time in the past") , } , _ => { } } self . context . schedule . last_update_check_time = now . into () ; }